1: import { Injectable } from '@angular/core';
2: import { ConfiguracionService } from './configuracion.service';
3: import { BehaviorSubject, fromEvent } from 'rxjs';
4: import { ImplicitAutenticationService } from './implicit_autentication.service';
5: 
6: @Injectable({
7:     providedIn: 'root',
8: })
9: export class MenuAplicacionesService {
10:     private dataFilterSubject = new BehaviorSubject([]);
11:     public eventFilter$ = this.dataFilterSubject.asObservable();
12: 
13:     private activo = new BehaviorSubject({});
14:     public activo$ = this.activo.asObservable();
15: 
16:     categorias: any;
17:     isLogin = false;
18:     roles: any;
19:     userInfo: any;
20:     public menuActivo: Boolean = false;
21: 
22:     constructor(
23:         private configuracionService: ConfiguracionService,
24:         private authenticationService: ImplicitAutenticationService,
25:     ) {
26:         fromEvent(document, 'mouseup').subscribe((data: any) => {
27:             if (this.activo) {
28:                 if (data.path) {
29:                     if ((
30:                         data.path
31:                             .map((info: any) => (info.localName))
32:                             .filter((dataFilter: any) => (dataFilter === 'ng-uui-menu-aplicaciones'))).length === 0) {
33:                         this.closePanel();
34:                     }
35:                 }
36:             }
37:         });
38:     }
39: 
40:     closePanel(): void {
41:         this.menuActivo = false;
42:         this.activo.next({ activo: this.menuActivo });
43:     }
44: 
45:     toogleMenuNotify(): void {
46:         this.menuActivo = !this.menuActivo;
47:         const data = { activo: this.menuActivo };
48:         this.activo.next(data);
49:     }
50: 
51:     init(categorias: any, userData:any): void {
52:         this.userInfo = userData;
53:         if (typeof this.userInfo.user.role !== 'undefined') {
54:             const roles = [...userData.user.role];
55:             this.isLogin = true;
56:             this.roles = roles.map((element) => ({ Nombre: element }));
57:             this.getAplication();
58:         }
59:         this.categorias = categorias;
60:     }
61: 
62:     public getAplication(): any {
63:         const idToken = localStorage.getItem('id_token');
64:         const accessToken = localStorage.getItem('access_token');
65:         const appsMenu = localStorage.getItem('apps_menu');
66:         const expectedContext = this.authenticationService.getSessionCacheKey('apps_menu');
67:         if (appsMenu && localStorage.getItem('apps_menu_context') === expectedContext) {
68:             try {
69:                 this.dataFilterSubject.next(JSON.parse(atob(appsMenu)));
70:                 return this.eventFilter$;
71:             } catch {
72:                 localStorage.removeItem('apps_menu');
73:                 localStorage.removeItem('apps_menu_context');
74:             }
75:         }
76: 
77:         localStorage.removeItem('apps_menu');
78:         localStorage.removeItem('apps_menu_context');
79:         if (idToken !== null && accessToken !== null) {
80:             this.configuracionService.post('aplicacion_rol/aplicacion_rol', this.roles)
81:                 .subscribe((data: any) => {
82:                     let nuevasAplicaciones = this.categorias.map((categoria: any) => {
83:                         categoria.aplicaciones = categoria.aplicaciones.filter((aplicacion: any) => (this.existe(aplicacion.nombre, data)));
84:                         categoria.aplicaciones = categoria.aplicaciones.map((app: any) => {
85:                             return { ...app, ...{ estilo_logo: app.estilo.split('-')[0] } };
86:                         });
87:                         return categoria;
88:                     });
89:                     nuevasAplicaciones = nuevasAplicaciones.filter((categoria: { aplicaciones: string | any[]; }) => (categoria.aplicaciones.length > 0));
90:                     this.dataFilterSubject.next(nuevasAplicaciones);
91:                     localStorage.setItem('apps_menu', btoa(JSON.stringify(nuevasAplicaciones)));
92:                     localStorage.setItem('apps_menu_context', expectedContext);
93:                 });
94:             return this.eventFilter$;
95:         }
96:     }
97: 
98:     existe(nombre: string, array: any): boolean {
99:         const filtro = array.filter((data: any) => (nombre.toLowerCase() === data.Nombre.toLowerCase()));
100:         return filtro.length > 0;
101:     }
102: 
103: }

